const tid=$('Params In').first().json['Table ID'];
const baseId=$('Params In').first().json['Clayroots Base ID'];
const resp=$('Check Table').first().json||{};
const t=(resp.tables||[]).find(x=>x.id===tid);
if(!t){ throw new Error('Table '+tid+' not found in base '+baseId+'.'); }
const names=(t.fields||[]).map(f=>f.name);
if(!(names.includes('Email')||names.includes('public_emails_clean'))){ throw new Error('Table "'+t.name+'" has no Email or public_emails_clean field. Aborting.'); }
return [{ json:{ table:t.name, hasEmail:true, startedAt:new Date().toISOString() } }];

const MV=[{name:'ok',color:'greenBright'},{name:'catch_all',color:'yellowBright'},{name:'invalid',color:'redBright'},{name:'disposable',color:'orangeLight2'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const BB=[{name:'verifying',color:'blueBright'},{name:'deliverable',color:'greenBright'},{name:'undeliverable',color:'redBright'},{name:'risky',color:'yellowBright'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const SRC=[{name:'P0',color:'blueBright'},{name:'P1',color:'cyanBright'},{name:'P2',color:'tealBright'},{name:'P3',color:'purpleBright'},{name:'none',color:'grayBright'}];
const ST=[{name:'done',color:'greenBright'},{name:'verifying',color:'blueBright'},{name:'no_email_found',color:'redBright'},{name:'error',color:'orangeBright'}];
const sel=(name,choices)=>({name,type:'singleSelect',options:{choices}});
const txt=(name)=>({name,type:'singleLineText'});
// 2026-08-12: no bare 'MV' - P0 is the pre-existing-address tier, so a verify-only pass writes MV P0,
// the same column the waterfall uses. 'Email Source' replaces 'Source' (Operator ruling: Email Source =
// which tier found the email; Contact Source = where the contact came from, owned by the builders).
// SRC carries P3 so this array stays byte-identical to Waterfall Emails' Field List.
const defs=[ sel('MV P0',MV), sel('BB',BB), txt('Final Email'), sel('Email Source',SRC), sel('Status',ST) ];
return defs.map(d=>({json:{def:d}}));

const row=$('Read Records').item.json; const f=row.fields||{};
const prior=((f['Final Email']||'')+'').trim();
const priorSrc=((f['Email Source']||f.Source||'')+'');
const wasDone=((f.Status||'')+'')==='done';
const existing=((prior||f.Email||(f.public_emails_clean||'').split(',')[0])||'').trim();
const slot=priorSrc||'P0';
// Write the verdict into the tier column the address actually came from. Fall back to MV P0 when the
// slot is not a known tier, or when that tier column does not exist on this table.
const tid=$('Params In').first().json['Table ID'];
let cols=[]; try{ const t=((($('Check Table').first().json)||{}).tables||[]).find(x=>x.id===tid); cols=((t||{}).fields||[]).map(x=>x.name); }catch(e){}
let mvCol='MV '+slot;
if(!/^P[0-3]$/.test(slot)||(cols.length&&!cols.includes(mvCol))) mvCol='MV P0';
const G=(n)=>{ try{ const v=$(n).item.json; return (v&&typeof v==='object')?v:null; }catch(e){ return null; } };
const mv0=G('MV');
const SK='skipped';
const MVOK=['ok','catch_all','invalid','disposable','unknown'];
const mvVal=(r)=> r?(MVOK.includes(r.result)?r.result:'error'):SK;
const mvErr=(r)=> r&&(r.resultcode===4||(r.error&&r.error!=='')||!MVOK.includes(r.result));
const IND=(r)=> r==='catch_all'||r==='unknown';
let final='',source='none',bb='skipped',pe='',ps='',resolved=false,verifying=false,errored=false;
if(existing&&mv0){ if(mv0.result==='ok'){final=existing;source=slot;resolved=true;} else if(IND(mv0.result)){verifying=true;bb='verifying';pe=existing;ps=slot;} else if(mvErr(mv0)){errored=true;} }
const status= resolved?'done':(verifying?'verifying':(errored?'error':'no_email_found'));
const mvOut= existing?mvVal(mv0):SK;
// A definitive negative is the only reason to clear an address. An indeterminate result (catch_all,
// unknown), an API error, or a missing response must never blank a Final Email that was already there.
const definitiveBad=!!(mv0&&(mv0.result==='invalid'||mv0.result==='disposable'));
const out={ id:row.id, 'BB':bb, 'Status':status, _pendEmail:pe, _pendSlot:ps, _mv:mvOut, _mvCol:mvCol, _wasDone:wasDone };
out[mvCol]=mvOut;
if(resolved){ out['Final Email']=final; out['Email Source']=source; out._preserved=false; out._blanked=false; }
else if(prior&&!definitiveBad){ out['Final Email']=prior; out['Email Source']=priorSrc||'none'; out._preserved=true; out._blanked=false; }
else { out['Final Email']=''; out['Email Source']='none'; out._blanked=!!prior; out._preserved=false; }
return { json: out };

const wfid='jtBHNttawTdjG6Tv';
const p=$('Params In').first().json;
const start=$('Email Guard').first().json.startedAt;
let tableName=p['Table ID']; try{ tableName=$('Email Guard').first().json.table||tableName; }catch(e){}
let rows=[]; try{ rows=$('Verdict').all().map(i=>i.json); }catch(e){}
let recIn=0; try{ recIn=$('Read Records').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
const c=(fn)=>rows.filter(fn).length;
const mv=(v)=>c(r=>r._mv===v);
const sd=$getWorkflowStaticData('global');
if(!sd._wfLogTotals || sd._wfLogTotals.execId!==String($execution.id)){ sd._wfLogTotals={ execId:String($execution.id), ok:0, catchAll:0, invalid:0, disposable:0, unknown:0, errd:0, skipped:0, verifying:0, recordsOut:0, preserved:0, blanked:0, reverified:0, p0:0, p1:0, p2:0, p3:0 }; }
const a=sd._wfLogTotals;
a.ok+=mv('ok'); a.catchAll+=mv('catch_all'); a.invalid+=mv('invalid'); a.disposable+=mv('disposable'); a.unknown+=mv('unknown'); a.errd+=mv('error'); a.skipped+=mv('skipped');
a.verifying+=c(r=>r.Status==='verifying');
a.preserved+=c(r=>r._preserved===true);
a.blanked+=c(r=>r._blanked===true);
a.reverified+=c(r=>r._wasDone===true);
a.p0+=c(r=>r._mvCol==='MV P0'); a.p1+=c(r=>r._mvCol==='MV P1'); a.p2+=c(r=>r._mvCol==='MV P2'); a.p3+=c(r=>r._mvCol==='MV P3');
a.recordsOut+=rows.length;
const recordsOut=a.recordsOut;
const cap=Number(p['Max Rows'])||100000;
const isFinal=recordsOut>=Math.min(recIn,cap);
const ms=Date.parse(start);
const dur=ms?Math.round((Date.now()-ms)/1000):null;
const trig=p['_launchRecordId']?'record':'form';
const pct=(n)=>recordsOut?Math.round((n/recordsOut)*1000)/10:0;
const desc=[
'**'+recIn+' read, '+recordsOut+' updated, '+a.errd+' errored**',
'',
'**Table:** '+tableName+' ('+p['Table ID']+')'+(p['View']?' · view '+p['View']:''),
'**Launch:** '+trig+'-launched · MillionVerifier pass, catch-alls handed to the BounceBan Poller',
'',
'**Verdicts**',
'- **ok:** '+a.ok+' ('+pct(a.ok)+'%)',
'- **catch_all:** '+a.catchAll,
'- **invalid:** '+a.invalid,
'- **disposable:** '+a.disposable,
'- **unknown:** '+a.unknown,
'- **errored:** '+a.errd+' · **skipped, no email on the row:** '+a.skipped,
'',
'**Verdict written into**',
'- MV P0: '+a.p0+' · MV P1: '+a.p1+' · MV P2: '+a.p2+' · MV P3: '+a.p3,
'',
'**Address safety**',
'- Existing Final Email kept through an indeterminate or errored check: '+a.preserved,
'- Cleared, definitive invalid or disposable only: '+a.blanked,
'- Rows already Status=done that were re-verified: '+a.reverified,
'',
'**Sent to BounceBan (Status=verifying):** '+a.verifying,
'',
'**Duration:** '+(dur!=null?dur+'s':'n/a')
].join('\n');
return [{ json:{ 'Automation':'Verify Emails', 'Run at': start||new Date().toISOString(), 'Target': p['Table ID'], 'Records In': recIn, 'Records Out': recordsOut, 'Execution ID': String($execution.id), 'Execution Link': 'https://n8n.flowroots.com/workflow/'+wfid+'/executions/'+$execution.id, 'Status': isFinal?(a.errd?'Succeeded with errors':'Succeeded'):'Running', 'Trigger': trig, 'Errors': a.errd, 'Duration s': dur, 'Description': desc } }];

const log=Object.assign({},$('Build Log').first().json);
let rec=[];
try{ const lc=$('Fetch Launch Record').first().json.fields.Client; if(Array.isArray(lc)&&lc.length&&lc[0]) rec=[lc[0]]; }catch(e){}
if(!rec.length){ try{const rc=$('Resolve Client').first().json; if(rc&&rc.id)rec=[rc.id];}catch(e){} }
if(rec.length){ log['Client']=rec; } else { delete log['Client']; }
return [{json:log}];

const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const client=$('Resolve Base').first().json;
const cf=client.fields||{};
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Table ID': ((f['Table ID']||'')+'').trim(),
  'Max Rows': f['Max Rows'] || 0,
  'View': ((f['View']||'')+'').trim(),
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];
